# 1. Add albumBoost to Song streams calculation
sed -i '/val hypeMult = if (song.weeksSinceRelease <= 1) {/i \                            val parentAlbum = state.albums.find { it.id == song.albumId }\n                            val albumBoost = if (parentAlbum != null && parentAlbum.isReleased && parentAlbum.rating > song.rating) {\n                                1f + ((parentAlbum.rating - song.rating) * 0.2f).coerceAtMost(0.8f)\n                            } else 1f' app/src/main/java/com/example/data/GameViewModel.kt

sed -i 's/val finalWeeklyStream = (baseGrowth \* song.rating \* qualityBoost \* trendMult \* eventMult \* wordOfMouth \* prestigeFactor \* viralMultiplier \* promoMult \* countryMult \* labelMarketingMult \* hypeMult \* distMult \* biopicMult \* adAgencyMult \* (Random.nextFloat() \* 0.3f + 0.85f)).toLong()/val finalWeeklyStream = (baseGrowth * song.rating * qualityBoost * trendMult * eventMult * wordOfMouth * prestigeFactor * viralMultiplier * promoMult * countryMult * labelMarketingMult * hypeMult * distMult * biopicMult * adAgencyMult * albumBoost * (Random.nextFloat() * 0.3f + 0.85f)).toLong()/g' app/src/main/java/com/example/data/GameViewModel.kt

# 2. Add preReleaseStreamsBoost to Album sales calculation
sed -i '/val marketingMult = when (album.marketingTier) {/i \                    val albumSongs = updatedSongs.filter { it.albumId == album.id }\n                    val totalPreReleaseStreams = albumSongs.sumOf { it.totalStreams }\n                    val preReleaseStreamsBoost = (totalPreReleaseStreams / 5000000f).coerceAtMost(3.0f)' app/src/main/java/com/example/data/GameViewModel.kt

sed -i 's/val currentSales = (baseSalesVal \* marketingMult \* decayPower \* (Random.nextFloat() \* 0.4f + 0.8f)).toLong().coerceAtLeast(0L)/val currentSales = (baseSalesVal * marketingMult * (1f + preReleaseStreamsBoost) * decayPower * (Random.nextFloat() * 0.4f + 0.8f)).toLong().coerceAtLeast(0L)/g' app/src/main/java/com/example/data/GameViewModel.kt
